const fleet = global.get("fleet");
const robotId = msg.req.params.id;

const robot = fleet?.robots?.[robotId];

if (!robot) {
    msg.statusCode = 404;
    msg.payload = {
        source: "GET_ROBOT",
        success: false,
        reason: "ROBOT_NOT_FOUND"
    };
    return msg;
}

msg.statusCode = 200;

msg.payload = {
    id: robot.id,
    station: robot.station,
    available: robot.available
};

return msg;

const fleet = global.get("fleet");
const robotId = msg.req.params.id;

const robot = fleet?.robots?.[robotId];

if (!robot) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        reason: "ROBOT_NOT_FOUND"
    };
    return msg;
}

const activeOrder = robot.activeOrderId
    ? fleet.orders[robot.activeOrderId]
    : null;

msg.statusCode = 200;

msg.payload = {
    robotId: robotId,
    activeOrder: activeOrder
};

return msg;

const fleet = global.get("fleet");
const orderId = msg.req.params.id;

const order = fleet?.orders?.[orderId];
const failures = global.get("mockFailures") || {};

if (failures.dropConfirmation) {
    msg.statusCode = 503;
    msg.payload = {
        success: false,
        reason: "SIMULATED_DROP_CONFIRMATION_FAILURE"
    };
    return msg;
}

if (!order) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        reason: "ORDER_NOT_FOUND"
    };
    return msg;
}

if (order.status !== "PENDING_DROP_CONFIRMATION") {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ORDER_NOT_PENDING_DROP"
    };
    return msg;
}

const robot = fleet?.robots?.[order.robotId];

if (!robot) {
    msg.statusCode = 500;
    msg.payload = {
        success: false,
        reason: "ROBOT_FOR_ORDER_NOT_FOUND"
    };
    return msg;
}

if (robot.activeOrderId !== orderId) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ACTIVE_ORDER_MISMATCH",
        robotActiveOrderId: robot.activeOrderId,
        requestedOrderId: orderId
    };
    return msg;
}

if (robot.station !== order.dropoff) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ROBOT_NOT_AT_DROPOFF",
        robotStation: robot.station,
        expectedStation: order.dropoff
    };
    return msg;
}

order.status = "COMPLETED";
order.dropConfirmedAt = new Date().toISOString();

robot.activeOrderId = null;

global.set("fleet", fleet);

msg.statusCode = 200;

msg.payload = {
    success: true,
    message: "Drop confirmed",
    orderId: orderId,
    robotId: order.robotId
};

return msg;

const fleet = global.get("fleet");
let nextOrderId = global.get("nextOrderId");

const request = msg.payload;
const failures = global.get("mockFailures") || {};

if (failures.orderCreation) {
    msg.statusCode = 503;
    msg.payload = {
        success: false,
        reason: "SIMULATED_ORDER_CREATION_FAILURE"
    };
    return msg;
}
if (
    !request ||
    !request.robotId ||
    !request.pickup ||
    !request.dropoff ||
    !request.palletId
) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        reason: "INVALID_ORDER_REQUEST"
    };
    return msg;
}

const robot = fleet?.robots?.[request.robotId];

if (!robot) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        reason: "ROBOT_NOT_FOUND"
    };
    return msg;
}

if (!robot.available) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ROBOT_NOT_AVAILABLE"
    };
    return msg;
}

if (robot.station !== request.pickup) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ROBOT_NOT_AT_PICKUP",
        robotStation: robot.station,
        expectedStation: request.pickup
    };
    return msg;
}

if (robot.activeOrderId !== null) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        reason: "ROBOT_ALREADY_HAS_ACTIVE_ORDER",
        activeOrderId: robot.activeOrderId
    };
    return msg;
}

const orderId = "O" + nextOrderId;

const newOrder = {
    id: orderId,
    robotId: request.robotId,
    pickup: request.pickup,
    dropoff: request.dropoff,
    palletId: request.palletId,
    status: "CREATED",
    createdAt: new Date().toISOString()
};

fleet.orders[orderId] = newOrder;
robot.activeOrderId = orderId;

global.set("fleet", fleet);
global.set("nextOrderId", nextOrderId + 1);

msg.statusCode = 201;

msg.payload = {
    success: true,
    message: "Order created",
    order: newOrder
};

return msg;

const request = msg.payload;

if (
    !request ||
    !request.robotId ||
    !request.stationId ||
    !request.newOrder ||
    !request.newOrder.pickup ||
    !request.newOrder.dropoff ||
    !request.newOrder.palletId
) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        stage: "request_validation",
        reason: "INVALID_TRIGGER_REQUEST"
    };

    msg.stopWorkflow = true;
    return msg;
}

msg.trigger = request;

//msg.method = "GET";
msg.url = "http://localhost:1880/mock/robots/" + encodeURIComponent(request.robotId);

msg.stopWorkflow = false;

return msg;

const robot = msg.payload;
const trigger = msg.trigger;

if (msg.statusCode !== 200) {
    msg.statusCode = 502;
    msg.payload = {
        success: false,
        stage: "robot_check",
        reason: "ROBOT_LOOKUP_FAILED"
    };
    return [msg, null];
}

if (!robot.available) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        stage: "robot_check",
        reason: "ROBOT_NOT_AVAILABLE",
        robotId: robot.id
    };
    return [msg, null];
}

if (robot.station !== trigger.stationId) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        stage: "robot_check",
        reason: "ROBOT_NOT_AT_DESIGNATED_STATION",
        robotId: robot.id,
        expectedStation: trigger.stationId,
        actualStation: robot.station
    };
    return [msg, null];
}

//continue workflow
msg.robot = robot;
//prepare next REST call.
//msg.method = "GET";
msg.url =
    "http://localhost:1880/mock/robots/" +
    encodeURIComponent(trigger.robotId) +
    "/active-order";

return [null, msg];

const result = msg.payload;
const activeOrder = result.activeOrder;

if (!activeOrder) {
    msg.activeOrder = null;
    return [msg, null, null];
}

msg.activeOrder = activeOrder;

if (activeOrder.status === "PENDING_DROP_CONFIRMATION") {
    return [null, msg, null];
}

//active order exists, but not in the state we are allowed to confirm
msg.statusCode = 409;
msg.payload = {
    success: false,
    stage: "active_order_check",
    reason: "ACTIVE_ORDER_NOT_PENDING_DROP",
    orderId: activeOrder.id,
    orderStatus: activeOrder.status
};

return [null, null, msg];

const order = msg.activeOrder;

//msg.method = "POST";

msg.url =
    "http://localhost:1880/mock/orders/" +
    encodeURIComponent(order.id) +
    "/drop-confirmation";

return msg;

const dropResult = msg.payload;

if (msg.statusCode !== 200 || !dropResult.success) {
    msg.statusCode = 502;
    msg.payload = {
        success: false,
        stage: "drop_confirmation",
        reason: "DROP_CONFIRMATION_FAILED",
        details: dropResult
    };

    return [null, msg];
}

//drop succeeded → continue to create new order
return [msg, null];

const trigger = msg.trigger;
//post
msg.url = "http://localhost:1880/mock/orders";

msg.payload = {
    robotId: trigger.robotId,
    pickup: trigger.newOrder.pickup,
    dropoff: trigger.newOrder.dropoff,
    palletId: trigger.newOrder.palletId
};

msg.headers = {
    "Content-Type": "application/json"
};

return msg;

const createResult = msg.payload;

if (msg.statusCode !== 201 || !createResult.success) {

    const dropWasPerformed = msg.activeOrder !== null;

    msg.statusCode = 502;

    msg.payload = {
        success: false,
        stage: "order_creation",
        reason: "ORDER_CREATION_FAILED",

        dropPerformed: dropWasPerformed,
        previousOrderId:
            dropWasPerformed
                ? msg.activeOrder?.id
                : null,

        details: createResult
    };

    return msg;
}

msg.statusCode = 200;

msg.payload = {
    success: true,
    stage: "completed",
    message: "Workflow completed successfully",
    robotId: msg.trigger.robotId,
    dropPerformed: msg.activeOrder !== null,
    previousOrderId: msg.activeOrder?.id || null,
    newOrder: createResult.order
};

return msg;

let fleet;
const scenario = msg.payload;
global.set("mockFailures", {
    dropConfirmation: false,
    orderCreation: false
});
switch (scenario) {

    case "pending_drop":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D2",
                    available: true,
                    activeOrderId: "O17"
                }
            },
            orders: {
                O17: {
                    id: "O17",
                    robotId: "R1",
                    pickup: "D1",
                    dropoff: "D2",
                    palletId: "P100",
                    status: "PENDING_DROP_CONFIRMATION"
                }
            }
        };
        break;

    case "no_active_order":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D2",
                    available: true,
                    activeOrderId: null
                }
            },
            orders: {}
        };
        break;

    case "unavailable":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D2",
                    available: false,
                    activeOrderId: null
                }
            },
            orders: {}
        };
        break;

    case "wrong_station":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D5",
                    available: true,
                    activeOrderId: null
                }
            },
            orders: {}
        };
        break;

    case "in_progress":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D2",
                    available: true,
                    activeOrderId: "O17"
                }
            },
            orders: {
                O17: {
                    id: "O17",
                    robotId: "R1",
                    pickup: "D1",
                    dropoff: "D2",
                    palletId: "P100",
                    status: "IN_PROGRESS"
                }
            }
        };
        break;
    case "drop_failure":
    fleet = {
        robots: {
            R1: {
                id: "R1",
                station: "D2",
                available: true,
                activeOrderId: "O17"
            }
        },
        orders: {
            O17: {
                id: "O17",
                robotId: "R1",
                pickup: "D1",
                dropoff: "D2",
                palletId: "P100",
                status: "PENDING_DROP_CONFIRMATION"
            }
        }
    };

    global.set("mockFailures", {
        dropConfirmation: true,
        orderCreation: false
    });
    break;

    case "create_failure":
        fleet = {
            robots: {
                R1: {
                    id: "R1",
                    station: "D2",
                    available: true,
                    activeOrderId: "O17"
                }
            },
            orders: {
                O17: {
                    id: "O17",
                    robotId: "R1",
                    pickup: "D1",
                    dropoff: "D2",
                    palletId: "P100",
                    status: "PENDING_DROP_CONFIRMATION"
                }
            }
        };

        global.set("mockFailures", {
            dropConfirmation: false,
            orderCreation: true
        });
        break;
    default:
        return null;
}

global.set("fleet", fleet);
global.set("nextOrderId", 18);

// message for next dashboard node
msg.payload = {
    scenario: scenario,
    fleet: fleet
};

return msg;

const fleet = global.get("fleet");
const robot = fleet?.robots?.R1;

const order = robot?.activeOrderId
    ? fleet.orders[robot.activeOrderId]
    : null;

return [
    { payload: robot?.id || "NONE" },
    { payload: robot?.station || "NONE" },
    { payload: robot?.available ? "YES" : "NO" },
    { payload: robot?.activeOrderId || "NONE" },
    { payload: order?.status || "NONE" },
    { payload: order?.pickup || "-" },
    { payload: order?.dropoff || "-" },
    { payload: order?.palletId || "-" }
];

msg.url = "http://localhost:1880/api/trigger";

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    robotId: "R1",
    stationId: "D2",
    newOrder: {
        pickup: "D2",
        dropoff: "D3",
        palletId: "P200"
    }
};

return msg;

const result = msg.payload;

return [
    {
        payload: result?.success === true
            ? "SUCCESS"
            : "FAILED"
    },
    {
        payload: result?.stage || "-"
    },
    {
        payload:
            result?.message ||
            result?.reason ||
            "-"
    },
    {
        payload:
            result?.dropPerformed === true
                ? "YES"
                : result?.dropPerformed === false
                    ? "NO"
                    : "-"
    },
    {
        payload: result?.previousOrderId || "-"
    },
    {
        payload: result?.newOrder?.id || "-"
    },
    {
        payload: result?.newOrder?.status || "-"
    }
];
